/* eslint-disable */
// ─────────────────────────────────────────────────────────────────────────────
// custom-sw.js — an APP-OWNED, fetch-intercepting ServiceWorker (Workbox-style).
//
// Hand-written on purpose — a plain static asset, not generated by the library.
// It demonstrates the "Axis A" fetch-control recipe:
//
//   • precache                       — static shell available before any network
//   • stale-while-revalidate by URL  — serve cache instantly, refresh in the bg
//   • offline fallback               — a synthesized Response when the net is gone
//
// IMPORTANT: this SW lives BELOW `ApiClient`. `ApiClient` has no idea it exists
// and its `baseQuery.fetchFn` is NOT touched. The SW transparently intercepts
// `fetch` at the platform level, so every request the client makes still shows
// up in DevTools → Network — but tagged "(ServiceWorker)". This is the opposite
// of `WorkerCacheStorage`, which short-circuits ABOVE fetch (a cache hit there
// produces NO Network row at all).
// ─────────────────────────────────────────────────────────────────────────────

const CACHE = 'custom-fetch-demo-v1'

// 1) Precache — the app shell, warmed on install so it is available offline.
const PRECACHE_URLS = ['/', '/index.html']

// Requests to this host are handled with stale-while-revalidate.
const SWR_HOST = 'pokeapi.co'

self.addEventListener('install', (event) => {
  // Activate this SW version immediately instead of waiting for old tabs to close.
  self.skipWaiting()
  event.waitUntil(
    caches.open(CACHE).then((cache) =>
      // Precache is best-effort: a missing shell asset must not break install.
      cache.addAll(PRECACHE_URLS).catch(() => undefined),
    ),
  )
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    Promise.all([
      // Drop stale cache versions.
      caches.keys().then((keys) =>
        Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))),
      ),
      // Start controlling already-open clients right away.
      self.clients.claim(),
    ]),
  )
})

self.addEventListener('fetch', (event) => {
  const request = event.request

  // Only GETs are cacheable in this demo.
  if (request.method !== 'GET') return

  const url = new URL(request.url)

  // Strategy dispatch BY URL — the whole point of an app-owned SW.
  if (url.hostname === SWR_HOST) {
    event.respondWith(staleWhileRevalidate(request, event))
    return
  }

  // Everything else: no respondWith() → default browser behavior.
})

// stale-while-revalidate: answer from cache immediately (if present) while a
// background refresh keeps the cache fresh. On a cold miss we wait for the
// network and, if it fails, serve the offline fallback.
async function staleWhileRevalidate(request, event) {
  const cache = await caches.open(CACHE)
  const cached = await cache.match(request)

  const networkFetch = fetch(request)
    .then((response) => {
      if (response && response.ok) cache.put(request, response.clone())
      return tag(response, 'network')
    })
    .catch(() => null)

  if (cached) {
    // Serve the stale copy now; keep the SW alive until the background revalidation
    // finishes via event.waitUntil — otherwise the browser may terminate the worker
    // before cache.put() lands and the cache never refreshes.
    if (event) event.waitUntil(networkFetch)
    return tag(cached, 'cache')
  }

  const fresh = await networkFetch
  if (fresh) return fresh
  return offlineFallback(request)
}

// Rebuild the response so both DevTools and the app can tell it came from the SW.
async function tag(response, via) {
  if (!response) return response
  const headers = new Headers(response.headers)
  headers.set('X-Served-By', 'ServiceWorker')
  headers.set('X-SW-Strategy', via) // 'cache' | 'network' | 'offline-fallback'
  const body = await response.clone().arrayBuffer()
  return new Response(body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  })
}

// Synthesized offline response — the request had no cached copy and the network
// is unreachable. A real app would return a cached shell / queued payload here.
function offlineFallback(request) {
  return new Response(
    JSON.stringify({
      offline: true,
      message: 'Served by the ServiceWorker offline fallback',
      url: request.url,
    }),
    {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'X-Served-By': 'ServiceWorker',
        'X-SW-Strategy': 'offline-fallback',
      },
    },
  )
}
